class ChainedHashTable:
    def __init__(self, capacity=8):
        self.capacity = capacity
        self.buckets = [[] for _ in range(capacity)]
        self.size = 0
        self.collisions = 0

    def put(self, key, value):
        bucket = self.buckets[hash(key) % self.capacity]
        if bucket:
            self.collisions += 1
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self.size += 1
        if self.size / self.capacity > 0.75:
            self._rehash()

    def get(self, key, default=None):
        for k, v in self.buckets[hash(key) % self.capacity]:
            if k == key:
                return v
        return default

    def _rehash(self):
        items = [it for b in self.buckets for it in b]
        self.capacity *= 2
        self.buckets = [[] for _ in range(self.capacity)]
        self.size = 0
        for k, v in items:
            self.put(k, v)

table = ChainedHashTable()
for i in range(20):
    table.put('feat_%d' % i, i * i)
print('容量', table.capacity, '元素数', table.size, '冲突次数', table.collisions)
print('查 feat_13 ->', table.get('feat_13'))
print('查缺失 key ->', table.get('feat_999', 'MISSING'))

