import heapq


def top_k_heap(nums, k):
    # 维护大小为 k 的最小堆: 堆顶是当前 k 个里最小的
    if k <= 0:
        return []
    heap = nums[:k]
    heapq.heapify(heap)
    for x in nums[k:]:
        if x > heap[0]:
            heapq.heapreplace(heap, x)
    return sorted(heap, reverse=True)


def sift_down(arr, i, n):
    while 2 * i + 1 < n:
        child = 2 * i + 1
        if child + 1 < n and arr[child + 1] < arr[child]:
            child += 1
        if arr[i] <= arr[child]:
            break
        arr[i], arr[child] = arr[child], arr[i]
        i = child


def build_heap(arr):
    # 自底向上建堆, 总代价 O(n)
    for i in range(len(arr) // 2 - 1, -1, -1):
        sift_down(arr, i, len(arr))
    return arr


data = [3, 1, 5, 12, 2, 11, 7, 9, 4]
print('Top-3 (堆)', top_k_heap(data, 3))
print('Top-3 (全排序)', sorted(data, reverse=True)[:3])
print('建堆后数组', build_heap(data[:]))

