from collections import deque


def bfs_shortest(graph, start, target):
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        if node == target:
            return dist[node]
        for nxt in graph[node]:
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                q.append(nxt)
    return -1


def topo_sort(n, edges):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1
    q = deque([i for i in range(n) if indegree[i] == 0])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)
    return order if len(order) == n else None


graph = {0: [1, 2], 1: [3], 2: [3, 4], 3: [5], 4: [5], 5: []}
print('0 到 5 的最短边数', bfs_shortest(graph, 0, 5))
print('拓扑序', topo_sort(6, [(0, 1), (0, 2), (1, 3), (2, 3), (2, 4), (3, 5), (4, 5)]))
print('有环图返回', topo_sort(3, [(0, 1), (1, 2), (2, 0)]))

import random


def quicksort(nums):
    if len(nums) <= 1:
        return nums
    pivot = random.choice(nums)
    left = [x for x in nums if x < pivot]
    mid = [x for x in nums if x == pivot]
    right = [x for x in nums if x > pivot]
    return quicksort(left) + mid + quicksort(right)


def merge_sort(nums):
    if len(nums) <= 1:
        return nums
    mid = len(nums) // 2
    left, right = merge_sort(nums[:mid]), merge_sort(nums[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    return out + left[i:] + right[j:]


def length_bucketed_batches(lengths, batch_size=4):
    # 按长度排序后分桶: 同 batch 内长度接近, padding 浪费大幅下降
    ordered = sorted(lengths)
    return [(ordered[i:i + batch_size], max(ordered[i:i + batch_size]))
            for i in range(0, len(ordered), batch_size)]


data = [5, 2, 9, 1, 5, 6]
print('快排', quicksort(data), '归并', merge_sort(data))
for chunk, pad_to in length_bucketed_batches([12, 800, 15, 780, 20, 810, 9, 799]):
    print('batch', chunk, 'pad 到', pad_to, '浪费 token', sum(pad_to - x for x in chunk))

