def search_range(nums, target):
    def bound(t, first):
        lo, hi, ans = 0, len(nums) - 1, -1
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            if nums[mid] > t or (first and nums[mid] == t):
                if nums[mid] == t:
                    ans = mid
                hi = mid - 1
            else:
                if nums[mid] == t:
                    ans = mid
                lo = mid + 1
        return ans

    return [bound(target, True), bound(target, False)]


